@layer base, components;

@layer base {
  #hero.btn { color: red; }
}

@layer components {
  .btn { color: blue; }
}

@layer base, theme;

@layer base {
  .btn { color: red !important; }
}

@layer theme {
  .btn { color: blue !important; }
}

.btn { color: green !important; }

.parent { color: green; }

.child {
  color: red;
  --c: 20px;
  color: var(--c);
}

.box {
  box-sizing: content-box;
  width: 200px;
  padding: 20px;
  border: 5px solid black;
}

/* <body><div class="parent"><p class="child">Hi</p></div></body> */
body    { font-size: 1rem; }
.parent { font-size: 1.25em; }
.child  { font-size: 1.5em; }

p.note { color: green; }
.note  { color: blue; }
p      { color: red; }
.note  { color: purple; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.card {
  box-sizing: border-box;
  width: 300px;
  padding: 0 24px;
  border: 2px solid #ccc;
}

.row { display: flex; }
.row > * { flex-basis: 100px; flex-shrink: 1; }
.a { flex-grow: 1; }
.b { flex-grow: 1; }
.c { flex-grow: 2; }

@layer reset, components;

@layer components {
  .btn { color: blue; }
}

@layer reset {
  #buy.btn { color: red; }
}

button { color: green; }

.box {
  box-sizing: content-box;
  font-size: 20px;
  width: calc(50% - 2rem);
  padding: 0 1em;
  border: 0;
}
